<?php require_once 'includes/db.php'; $pageTitle='Produtos'; require 'includes/header.php'; $rows=$pdo->query('SELECT * FROM produtos ORDER BY id DESC')->fetchAll(); ?>
<div class="page-heading"><div><h1 class="h3 mb-1">Produtos</h1><p class="text-secondary mb-0">Cadastre os itens que poderão compor os fretes.</p></div><a class="btn btn-primary" href="produto_form.php">+ Cadastrar produto</a></div>
<div class="card p-3"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Nome</th><th>Peso (kg)</th><th>Valor (R$)</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['nome'])?></td><td><?=number_format($r['peso'],2,',','.')?></td><td><?=number_format($r['valor'],2,',','.')?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="produto_form.php?id=<?=$r['id']?>">Editar</a> <a class="btn btn-sm btn-outline-danger" onclick="return confirm('Excluir este produto?')" href="delete.php?tipo=produto&id=<?=$r['id']?>">Excluir</a></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="4" class="text-center text-secondary">Nenhum produto cadastrado.</td></tr><?php endif; ?></tbody></table></div></div><?php require 'includes/footer.php'; ?>
